            "v0/ns/default/wt/LargeIOWorkflow/wi/f1d2a4ac-f8cb-45d3-908c-93a0f33ab245/ri/null/d/" +
                "sha256/6ca22c34560cf35ac24427dc7619c9ab472a82cf18f286f27871649a2b5608c8",
            reference.ClaimData["key"]);
        var details = Assert.Single(payload.ExternalPayloads);
        Assert.Equal(385, details.SizeBytes);
    }

    [Fact]
    public void ParseReference_UnknownJsonField_Parses()
    {
        var payload = new Payload()
        {
            Data = ByteString.CopyFromUtf8(
                @"{""driverName"":""my-driver"",""claimData"":{""key"":""k""},""futureField"":1}"),
        };
        payload.Metadata["encoding"] = ByteString.CopyFromUtf8("json/protobuf");
        payload.Metadata["messageType"] =
            ByteString.CopyFromUtf8("temporal.api.sdk.v1.ExternalStorageReference");

        var reference = ExternalStorageReferences.ParseReference(payload);
        Assert.Equal("my-driver", reference.DriverName);
        Assert.Equal("k", reference.ClaimData["key"]);
    }

    [Fact]
    public void ParseReference_MalformedReferenceData_Throws()
    {
        var payload = new Payload() { Data = ByteString.CopyFromUtf8("not json") };
        payload.Metadata["encoding"] = ByteString.CopyFromUtf8("json/protobuf");
        payload.Metadata["messageType"] =
            ByteString.CopyFromUtf8("temporal.api.sdk.v1.ExternalStorageReference");

        var err = Assert.Throws<InvalidExternalStorageReferenceException>(() =>
            ExternalStorageReferences.ParseReference(payload));

        // The raw protobuf failure is wrapped, because malformed JSON and valid JSON of the wrong
        // shape throw two unrelated exception types.
        Assert.IsAssignableFrom<Exception>(err.InnerException);
    }

    [Theory]
    [InlineData("json/plain", null)]
    [InlineData("binary/protobuf", "temporal.api.sdk.v1.ExternalStorageReference")]
    [InlineData("json/protobuf", "temporal.api.common.v1.Payload")]
    [InlineData("json/protobuf", null)]
    [InlineData(null, "temporal.api.sdk.v1.ExternalStorageReference")]
    public void IsReference_NonReferencePayload_ReturnsFalse(
        string? encoding, string? messageType)
    {
        var payload = new Payload() { Data = ByteString.CopyFromUtf8("{}") };
        if (encoding != null)
        {
            payload.Metadata["encoding"] = ByteString.CopyFromUtf8(encoding);
        }
        if (messageType != null)
        {
            payload.Metadata["messageType"] = ByteString.CopyFromUtf8(messageType);
        }

        Assert.False(ExternalStorageReferences.IsReference(payload));
        Assert.Throws<InvalidExternalStorageReferenceException>(() =>
            ExternalStorageReferences.ParseReference(payload));
    }
}

namespace Temporalio.Tests.Converters;

using Temporalio.Converters;
using Xunit;

public class PayloadValidationErrorTests
{
    [Fact]
    public void CreateException_WithDetails_CreatesExpectedApplicationFailure()
    {
        var details = new { Path = "name", Reason = "must not be empty" };

        var exception = PayloadValidationError.CreateException(details);

        Assert.Equal("Payload validation failed", exception.Message);
        Assert.Equal("PayloadValidationError", exception.ErrorType);
        Assert.True(exception.NonRetryable);
        Assert.Equal(1, exception.Details.Count);
        Assert.Same(details, exception.Details.ElementAt<object>(0));
    }

    [Fact]
    public void CreateException_WithNullDetails_CreatesApplicationFailureWithoutDetails()
    {
        var exception = PayloadValidationError.CreateException(null);

        Assert.Equal("Payload validation failed", exception.Message);
        Assert.Equal("PayloadValidationError", exception.ErrorType);
        Assert.True(exception.NonRetryable);
        Assert.Equal(0, exception.Details.Count);
    }
}
